#include <vector>
#include <iostream>

int main() {
    std::vector<int> v1 = {1, 2, 3};
    std::vector<int> v2 = {9, 8, 7};

    // O(1) operation, preferred over assignment (v1 = v2)
    v1.swap(v2);

    std::cout << "v1[0]: " << v1[0] << " (was 1, now 9)\n";
    std::cout << "v2[0]: " << v2[0] << " (was 9, now 1)\n";

    // Guaranteed noexcept for vector
    // std::swap(v1, v2); // Equivalent non-member call
}
